effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec2 d = vec2(flux * 0.01 * sin(uv.y * 50.0 + acTime), 0.0);
float r = floor(texture2DCv(inputImg.texture, uv - d * chroma).r * steps) / steps;
float g = floor(texture2DCv(inputImg.texture, uv).g * steps) / steps;
float b = floor(texture2DCv(inputImg.texture, uv + d * chroma).b * steps) / steps;
gl_FragColor = vec4(r, g, b, texture2DCv(inputImg.texture, uv).a);
}
